# Own-wording subclasses of Griffon's Saddlebag Book 1 (2024). Shape of tvss_sub_wizard.py and tee24_sub.py.
def _arr(a, b, c, d, e):
    # 20 entries indexed by level 1..20: level 3 to 6 = a, 7 to 9 = b, 10 to 14 = c, 15 to 17 = d, 18 and up = e
    return [0, 0] + [a] * 4 + [b] * 3 + [c] * 5 + [d] * 3 + [e] * 3

